// Decides which BU/period pairs to build. Scheduled runs build the previous completed ISO week or calendar
// month in Asia/Jakarta. Webhook runs must name the period explicitly; nothing is guessed.
const BUS = ['bu1', 'bu2'];
const PERIOD = /^\d{4}-(W\d{2}|\d{2})$/;
const pad = (n) => String(n).padStart(2, '0');

function jakartaToday(value) {
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(value);
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  return new Date(Date.UTC(get('year'), get('month') - 1, get('day')));
}

function isoWeekLabel(date) {
  const thursday = new Date(date);
  thursday.setUTCDate(date.getUTCDate() + 3 - ((date.getUTCDay() + 6) % 7));
  const year = thursday.getUTCFullYear();
  const jan4 = new Date(Date.UTC(year, 0, 4));
  const week = 1 + Math.round(((thursday - jan4) / 86400000 - 3 + ((jan4.getUTCDay() + 6) % 7)) / 7);
  return `${year}-W${pad(week)}`;
}

function previousWeek(today) {
  const d = new Date(today);
  d.setUTCDate(d.getUTCDate() - 7);
  return isoWeekLabel(d);
}

function previousMonth(today) {
  const y = today.getUTCFullYear();
  const m = today.getUTCMonth();
  return m === 0 ? `${y - 1}-12` : `${y}-${pad(m)}`;
}

const executed = (name) => {
  try { return $(name).isExecuted === true; } catch (e) { return false; }
};

const input = $input.first().json;
const today = jakartaToday(input.timestamp ? new Date(input.timestamp) : new Date());
let trigger;
let bus = BUS;
let period;

if (executed('Webhook Generate')) {
  trigger = 'webhook';
  const body = input.body || {};
  const requested = String(body.bu || 'all').toLowerCase();
  if (requested !== 'all' && !BUS.includes(requested)) throw new Error(`bu harus salah satu dari: all, ${BUS.join(', ')}`);
  if (!PERIOD.test(String(body.period || ''))) throw new Error('period wajib diisi dengan format YYYY-Www atau YYYY-MM');
  bus = requested === 'all' ? BUS : [requested];
  period = String(body.period);
} else if (executed('Schedule Monthly')) {
  trigger = 'monthly';
  period = previousMonth(today);
} else {
  trigger = executed('Schedule Weekly') ? 'weekly' : 'manual';
  period = previousWeek(today);
}

return [{ json: { trigger, plans: bus.map((bu) => ({ bu, period })) } }];

// Turns the Tracker rows into one CSV per planned report. Only the columns the generator needs are kept, so PIC
// names, phone numbers, emails and CRM links never leave n8n. Dates arrive as Google Sheets serial numbers and are
// written as ISO dates, which removes any M/D versus D/M ambiguity.
const COLUMNS = ["Company", "Channel", "Source", "Campaign", "Campaign Hardware", "Industry", "Remark", "Inbound Date", "MQL Date", "Proposal Price Quote Date", "ARR + OTF (Tanpa PPN)", "Deal Won Date", "Total Contract Deal Won", "BU", "Record Key", "SQL Date", "Total Contract SQL"];
const DATE_COLUMNS = new Set(["Inbound Date", "MQL Date", "Proposal Price Quote Date", "Deal Won Date", "SQL Date"]);
const MONEY_COLUMNS = new Set(["ARR + OTF (Tanpa PPN)", "Total Contract Deal Won", "Total Contract SQL"]);
const SERIAL_EPOCH = Date.UTC(1899, 11, 30);
const normalize = (name) => String(name).replace(/\s+/g, ' ').trim();

function cell(column, value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'number') {
    if (DATE_COLUMNS.has(column)) return new Date(SERIAL_EPOCH + Math.floor(value) * 86400000).toISOString().slice(0, 10);
    if (MONEY_COLUMNS.has(column)) return String(Math.round(value * 100) / 100);
    return String(value);
  }
  return String(value).trim();
}

const quote = (text) => (/[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text);

const rows = [];
let missing = null;
for (const item of $input.all()) {
  const byName = {};
  for (const [key, value] of Object.entries(item.json)) byName[normalize(key)] = value;
  if (missing === null) {
    missing = COLUMNS.filter((column) => !(column in byName));
    if (missing.length) throw new Error(`Kolom tidak ada di sheet: ${missing.join(', ')}`);
  }
  const values = COLUMNS.map((column) => cell(column, byName[column]));
  if (values.some((v) => v !== '')) rows.push(values.map(quote).join(','));
}
if (!rows.length) throw new Error('Sheet tidak mengembalikan baris data');

const csv = [COLUMNS.map(quote).join(','), ...rows].join('\n') + '\n';
const plans = $('Normalize Plan').first().json.plans;
return plans.map((plan) => ({ json: { bu: plan.bu, period: plan.period, csv, rows: rows.length } }));

// Maps each generator response onto the parameters of sql/insert_run.sql.
return $input.all().map((item) => {
  const r = item.json;
  const table = r.audit.inputs.table;
  const params = [
    r.bu, r.period, r.period_kind, r.period_start, r.period_end, r.source_sha256, r.generator_version,
    table.rows_total, table.rows_in_bu, table.rows_without_bu,
    JSON.stringify(r.audit.metrics), JSON.stringify(r.audit), JSON.stringify(r.facts), JSON.stringify(r.analysis_keys),
    r.html,
  ];
  return { json: { params, bu: r.bu, period: r.period, metrics: r.audit.metrics.now, rows_without_bu: table.rows_without_bu, rows_in_bu: table.rows_in_bu } };
});

// Aggregate-only summary for Telegram and for the webhook response. No customer data.
const prepared = $('Prepare Insert').all();
const money = (n) => 'Rp ' + Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
return $input.all().map((saved, i) => {
  const p = prepared[i].json;
  const row = saved.json;
  const m = p.metrics;
  const state = row.inserted ? 'tersimpan' : 'sudah ada (input identik, tidak ditulis ulang)';
  const lines = [
    `Laporan ${p.bu.toUpperCase()} ${p.period} ${state}`,
    `Submission ${m['Submission']} · MQL ${m['MQL']} · SQL ${m['SQL']} · SQL Value ${money(m['SQL Value'])} · Deal Won ${m['Deal Won']} (provisional)`,
    `Baris di BU: ${p.rows_in_bu} · tanpa BU (tidak dihitung): ${p.rows_without_bu}`,
    `Run: ${String(row.run_id).slice(0, 8)}`,
  ];
  return { json: { bu: p.bu, period: p.period, run_id: row.run_id, inserted: row.inserted, text: lines.join('\n') } };
});

// The generator error is a short validation message (missing column, bad date, duplicate key). It never echoes a row.
const plan = $('Build CSV').item.json;
const raw = $json.error ? JSON.stringify($json.error) : JSON.stringify($json);
let message = raw;
try {
  const parsed = JSON.parse(raw);
  message = (parsed.error && (parsed.error.message || parsed.error)) || parsed.message || raw;
} catch (e) { /* keep raw */ }
return [{ json: { text: `Laporan ${plan.bu.toUpperCase()} ${plan.period} GAGAL dibuat: ${String(message).slice(0, 300)}` } }];
